bounded_host_request.command:
set -euo pipefail
n=gace-createvdobot-videobot-poll-1
pg=deploy-postgres-1
user="$(docker exec "$pg" sh -c 'printf %s "$POSTGRES_USER"')"
cursor="$(docker exec "$pg" psql -U "$user" -d videobot -Atc "SELECT last_update_id FROM videobot_poll_cursor WHERE consumer_id='createvdobot'")"
test "$cursor" = 2956731 || { echo CURSOR_CHANGED_ABORT; exit 81; }
digest="$(docker exec "$pg" psql -U "$user" -d videobot -Atc "SELECT payload_sha256 FROM videobot_webhook_updates WHERE update_id=2956732 AND status='needs_reconcile'")"
test "${#digest}" -eq 64 || { echo RECEIPT_CHANGED_ABORT; exit 82; }
token="$(docker inspect -f '{{range .Mounts}}{{if eq .Destination "/run/secrets/videobot_telegram_token"}}{{.Source}}{{end}}{{end}}' "$n")"
test -f "$token" || exit 83
docker stop -t 15 "$n" >/dev/null
restore(){ docker start "$n" >/dev/null 2>&1 || true; }
trap restore EXIT
docker run -i --rm --network deploy_default --pull never --mount "type=bind,source=$token,target=/run/secrets/videobot_telegram_token,readonly" --entrypoint node -e EXPECTED_SHA256="$digest" create-videobot:local-poll --input-type=module - <<'NODE'
import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {setDefaultResultOrder} from 'node:dns';
import {setDefaultAutoSelectFamily} from 'node:net';
setDefaultResultOrder('ipv4first');setDefaultAutoSelectFamily(false);
const token=readFileSync('/run/secrets/videobot_telegram_token','utf8').trim();
const r=await fetch('https://api.telegram.org/bot'+token+'/getUpdates',{method:'POST',
 headers:{'Content-Type':'application/json'},
 body:JSON.stringify({offset:2956732,limit:1,timeout:0}),
 signal:AbortSignal.timeout(15000)});
const d=await r.json();
if(!r.ok||d.ok!==true||!Array.isArray(d.result))throw Error('READ_ONLY_TELEGRAM_QUERY_FAILED');
const u=d.result[0];
if(!u||u.update_id!==2956732)throw Error('EXPECTED_UPDATE_NOT_PRESENT');
const sha=createHash('sha256').update(JSON.stringify(u)).digest('hex');
console.log('UPDATE_ID_MATCH=PASS');
console.log('PAYLOAD_HASH_MATCH='+(sha===process.env.EXPECTED_SHA256?'YES':'NO'));
const v=u.message?.successful_payment?'payment':
 u.purchased_paid_media?'paid_media':
 u.pre_checkout_query?'pre_checkout':
 u.message?(/^\/start(?:@[A-Za-z0-9_]+)?$/.test(u.message.text??'')?'plain_start':
 /^\/start(?:@[A-Za-z0-9_]+)? sticker$/.test(u.message.text??'')?'sticker_start':'other_message'):
 u.callback_query?(/^menu:/.test(u.callback_query.data??'')?'menu_callback':
 /^sticker:/.test(u.callback_query.data??'')?'sticker_callback':'other_callback'):'other_update';
console.log('BLOCKED_UPDATE_KIND='+v);
NODE
echo PENDING_EVENT_CLASSIFIED=PASS
